import React, { useEffect, useState } from "react";
import axios from "axios";
import "./dashboard.css";

function PomodoroTimer() {
  const userId = localStorage.getItem("user_id");

  const [secondsLeft, setSecondsLeft] = useState(1500);
  const [running, setRunning] = useState(false);
  const [courseId, setCourseId] = useState("");
  const [topic, setTopic] = useState("");
  const [courses, setCourses] = useState([]);

  useEffect(() => {
    axios.get("http://127.0.0.1:8000/courses").then((res) => {
      setCourses(res.data.courses || []);
    });
  }, []);

  useEffect(() => {
    if (!running) return;

    const timer = setInterval(() => {
      setSecondsLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setRunning(false);
          handleAutoSave();
          return 1500;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [running]);

  const formatTime = () => {
    const min = Math.floor(secondsLeft / 60);
    const sec = secondsLeft % 60;
    return `${min}:${sec < 10 ? "0" : ""}${sec}`;
  };

  const handleAutoSave = async () => {
    if (!courseId || !topic) return;

    await axios.post("http://127.0.0.1:8000/study-log", {
      user_id: parseInt(userId),
      course_id: parseInt(courseId),
      study_date: new Date().toISOString().split("T")[0],
      hours: 0.5,
      topic: `${topic} (Pomodoro Session)`
    });

    window.dispatchEvent(new Event("plannerUpdated"));
    alert("Pomodoro session saved as study log");
  };

  return (
    <div className="section-card">
      <h4>Pomodoro Timer</h4>

      <select
        className="select"
        value={courseId}
        onChange={(e) => setCourseId(e.target.value)}
      >
        <option value="">Select Course</option>
        {courses.map((c) => (
          <option key={c.id} value={c.id}>
            {c.title}
          </option>
        ))}
      </select>

      <input
        className="input"
        placeholder="Topic"
        value={topic}
        onChange={(e) => setTopic(e.target.value)}
      />

      <div style={{ fontSize: "42px", fontWeight: "bold", margin: "20px 0" }}>
        {formatTime()}
      </div>

      <div className="btn-row">
        <button className="btn btn-primary" onClick={() => setRunning(true)}>
          Start
        </button>
        <button className="btn btn-secondary" onClick={() => setRunning(false)}>
          Pause
        </button>
        <button
          className="btn btn-danger"
          onClick={() => {
            setRunning(false);
            setSecondsLeft(1500);
          }}
        >
          Reset
        </button>
      </div>
    </div>
  );
}

export default PomodoroTimer;
